            min_length=1,
            pattern="^(?![Ss][Yy][Nn][Tt][Hh][Èè][Ss][Ee]$|[Hh][Oo][Rr][Ss] [Ss][Oo][Uu][Ss]-[Pp][Rr][Oo][Jj][Ee][Tt]$)[^:\\\\/?*\\[\\]]*[^:\\\\/?*\\[\\]\\s][^:\\\\/?*\\[\\]]*$",
